```groovy
// gradle.properties (enable local build cache)
org.gradle.caching=true

// settings.gradle (configure remote cache for team sharing)
buildCache {
    local {
        enabled = true
    }
    remote(HttpBuildCache) {
        url = 'https://cache.example.com/'
        push = true  // CI can push, developers pull
    }
}

// Example: first build (cache miss)
./gradlew clean build
// Output: 15 tasks executed, 0 from cache
// Build time: 45 seconds

// Example: second build with no changes (cache hit)
./gradlew clean build
// Output: 15 tasks executed, 15 from cache
// Build time: 5 seconds

// Incremental build (change one file)
// Edit src/main/java/com/example/OrderService.java
./gradlew build
// Output: 3 tasks executed (compileJava, classes, jar), 12 up-to-date
// Build time: 8 seconds
```

